mapper.select:
SELECT f.feedback_id AS feedbackId, f.user_id AS userId, u.username AS username, u.name AS userName, f.category AS category, f.content AS content, f.created_at AS createdAt, f.updated_at AS updatedAt, f.handled AS handled, f.handled_at AS handledAt, h.name AS handledByName,
CASE WHEN f.image_keys IS NULL OR f.image_keys = '' OR f.image_keys = '[]' THEN 0 ELSE JSON_LENGTH(f.image_keys) END AS imageCount FROM feedback f LEFT JOIN user u ON u.user_id = f.user_id LEFT JOIN user h ON h.user_id = f.handled_by
f.is_deleted = 0
AND f.category = #{category}
AND f.handled = #{handled}
ORDER BY f.created_at DESC, f.feedback_id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM feedback

    is_deleted = 0

        AND category = #{category}


        AND handled = #{handled}
